
/* A local re-embedding of the closed star of one vertex, not a global surface. */
function vertexNeighborhood(triples, center, fold = 1) {
  const successor = new Map();
  triples.forEach((t, face) => {
    const i = t.indexOf(center);
    if (i >= 0) successor.set(t[(i + 1) % 3], {next:t[(i + 2) % 3], face});
  });
  if (successor.size !== 14) throw new Error('Expected fourteen incident faces');
  const ring = [], first = Math.min(...successor.keys());
  let current = first;
  do {
    if (ring.includes(current) || !successor.has(current)) throw new Error('Invalid vertex link');
    ring.push(current); current = successor.get(current).next;
  } while (current !== first);
  if (ring.length !== 14) throw new Error('The vertex link is not one fourteen-cycle');
  // Alternating heights make every triangle equilateral at full fold.
  // Projected wedges have disjoint interiors, so this disk cannot self-intersect.
  const step = 2 * Math.PI / 14;
  const height = fold * Math.sqrt((2 * Math.cos(step) - 1) / 3);
  const vertices = Array.from({length:15}, () => [0,0,0]);
  ring.forEach((v,i) => {const angle = Math.PI/2 + i*step;
    vertices[v-1] = [Math.cos(angle), Math.sin(angle), (i%2 ? -1:1)*height];});
  const paths = {}, incident = [];
  ring.forEach(v => {
    const {next, face} = successor.get(v); incident.push(face);
    [[center,v],[v,next]].forEach(([a,b]) => {
      paths[[a,b].sort((x,y)=>x-y).join('-')] = [vertices[a-1],vertices[b-1],null];
    });
  });
  return {triples, vertices, paths, ring, incident};
}
